const companies = $input.all().map(i => ({
  name: i.json.name,
  ats: i.json.ats_type,
  id: i.json.ats_id
}));
const KW=["ai","ml","machine learning","genai","llm","nlp","computer vision","data scientist","mlops","ai engineer","research scientist","deep learning","generative","foundation model"];
const hasAI=t=>{const l=(t||"").toLowerCase();return KW.some(k=>l.includes(k));};
const strip=h=>(h||"").replace(/<[^>]+>/g," ").replace(/\s{2,}/g," ").trim().slice(0,3000);
const results=[];const seen=new Set();
for(const c of companies){
  try{
    let url;
    if(c.ats==="greenhouse")url="https://boards-api.greenhouse.io/v1/boards/"+c.id+"/jobs?content=true";
    else if(c.ats==="lever")url="https://api.lever.co/v0/postings/"+c.id+"?content=true";
    else url="https://api.ashbyhq.com/posting-api/job-board/"+c.id;
    const r=await fetch(url,{headers:{"User-Agent":"JobAgent/1.0"}});
    if(!r.ok)continue;
    const d=await r.json();
    let jobs=[];
    if(c.ats==="greenhouse")jobs=(d.jobs||[]).filter(j=>hasAI(j.title)).map(j=>({company:c.name,role:j.title,jd_url:j.absolute_url||"",jd_text:strip(j.content),ats_type:"greenhouse",location:(j.location&&j.location.name)||"Remote",status:"scraped"}));
    else if(c.ats==="lever")jobs=(Array.isArray(d)?d:[]).filter(j=>hasAI(j.text)).map(j=>({company:c.name,role:j.text,jd_url:j.hostedUrl||"",jd_text:strip(j.descriptionBody||j.description),ats_type:"lever",location:(j.categories&&j.categories.location)||"Remote",status:"scraped"}));
    else jobs=((d.jobPostings||[])).filter(j=>hasAI(j.title)).map(j=>({company:c.name,role:j.title,jd_url:j.externalLink||"",jd_text:strip(j.descriptionBody),ats_type:"ashby",location:(j.locationNames&&j.locationNames[0])||"Remote",status:"scraped"}));
    for(const job of jobs){if(job.jd_url&&!seen.has(job.jd_url)){seen.add(job.jd_url);results.push({json:job});}}
  }catch(e){}
}
return results.length?results:[{json:{jd_url:"",status:"scraped"}}];

const item = $input.first().json;
const prompt = "Score this job against candidate profile.\n\nCANDIDATE: AI/ML Engineer, 3+ yrs Python/PyTorch/LangChain/LLMs/MLOps. B.Tech CS.\n\nJOB (" + item.company + " — " + item.role + "):\n" + (item.jd_text||"").slice(0,1500) + "\n\nReturn ONLY valid JSON (no markdown):\n{\"match_score\":<0-100>,\"matched_skills\":[\"skill\"],\"missing_skills\":[\"skill\"],\"match_justification\":\"3 concise bullet points\"}";
return [{json:{
  _job_id: item.id,
  gemini_request:{
    systemInstruction:{parts:[{text:"You are an expert ATS resume analyst for AI/ML roles. Return valid JSON only, no markdown fences."}]},
    contents:[{role:"user",parts:[{text:prompt}]}],
    generationConfig:{temperature:0.1,maxOutputTokens:512,responseMimeType:"application/json"}
  }
}}];

const resp = $input.first().json;
const text = (resp.candidates&&resp.candidates[0]&&resp.candidates[0].content&&resp.candidates[0].content.parts&&resp.candidates[0].content.parts[0]&&resp.candidates[0].content.parts[0].text)||'{}';
const clean = text.replace(/```json[\s\S]*?```|```[\s\S]*?```/g,'').trim();
try {
  const p = JSON.parse(clean);
  return [{json:{match_score:p.match_score||0,match_justification:p.match_justification||"",missing_skills:p.missing_skills||[],matched_skills:p.matched_skills||[],status:(p.match_score||0)>=60?"matched":"scraped"}}];
} catch(e) {
  return [{json:{match_score:0,match_justification:"Parse failed",missing_skills:[],matched_skills:[],status:"scraped"}}];
}

return [
  {json:{body:{q:'site:boards.greenhouse.io ("AI Engineer" OR "ML Engineer" OR "LLM" OR "MLOps") India', gl:'in', num:30}}},
  {json:{body:{q:'site:jobs.lever.co ("AI Engineer" OR "machine learning" OR "data scientist") India', gl:'in', num:30}}},
  {json:{body:{q:'site:jobs.ashbyhq.com ("AI" OR "machine learning" OR "LLM") India', gl:'in', num:30}}}
];
